"""⚠️ SECURITY: `run_command` executes shell commands generated by the language
model on the machine running this app. Commands outside a small read/test
allowlist require human approval in Slack before they run (see
`agent/approvals.py`), but a shell is expressive and approval is the real gate —
only ever run this against trusted, throwaway repositories in the session temp
directory. See the README security section.
"""

import subprocess
from pathlib import Path

from agents import function_tool
from agents.run_context import RunContextWrapper

from agent.approvals import run_command_needs_approval
from agent.deps import AgentDeps

# Cap any single command so a hung/looping command can't wedge the session.
COMMAND_TIMEOUT_SECONDS = 120


@function_tool(needs_approval=run_command_needs_approval)
def run_command(wrapper: RunContextWrapper[AgentDeps], command: str) -> str:
    """Run a shell command in the session's working directory and return its output.

    Use it to inspect, build, test, and edit the cloned repository (grep, cat,
    sed, pytest, git, and so on). Clone a repo with `clone_repo` first. Safe
    read/test commands run immediately; anything else asks the user to approve
    it in Slack before running.

    Args:
        command: The shell command to run, executed with the cloned repo as cwd.
    """
    session = wrapper.context.session
    if session.stopped:
        return "The user stopped this session. Do not run more commands."
    if not session.workdir or not Path(session.workdir).is_dir():
        return "No working directory yet — call clone_repo first."

    try:
        result = subprocess.run(
            command,
            shell=True,
            cwd=session.workdir,
            capture_output=True,
            text=True,
            timeout=COMMAND_TIMEOUT_SECONDS,
            check=False,
        )
    except subprocess.TimeoutExpired:
        return f"Command timed out after {COMMAND_TIMEOUT_SECONDS}s: {command}"

    out = (result.stdout or "").strip()
    err = (result.stderr or "").strip()
    parts = [f"exit={result.returncode}"]
    if out:
        parts.append(f"stdout:\n{out[:4000]}")
    if err:
        parts.append(f"stderr:\n{err[:2000]}")
    return "\n".join(parts)
